// BLE termometre: sıcaklığı bildir, LED'i yazmayla yönet.
// Telefona "nRF Connect" ya da "LightBlue" uygulamasını kur, KendinYap-Termometre'ye bağlan.
#include <BLEDevice.h>
#include <BLEServer.h>
#include <BLEUtils.h>
#include <BLE2902.h>
#include <DHT.h>

#define SERVIS_UUID   "4fafc201-1fb5-459e-8fcc-c5c9c331914b"
#define SICAKLIK_UUID "beb5483e-36e1-4688-b7f5-ea07361b26a8"
#define LED_UUID      "e3223119-9445-4e96-a4a1-85358c4046a2"

const int DHT_PIN = 4;
const int LED_PIN = 2;
DHT dht(DHT_PIN, DHT22);
BLECharacteristic* sicaklikOzelligi;
bool telefonBagli = false;

class SunucuOlaylari : public BLEServerCallbacks {
  void onConnect(BLEServer*) override { telefonBagli = true; Serial.println("Telefon baglandi"); }
  void onDisconnect(BLEServer* s) override {
    telefonBagli = false;
    Serial.println("Telefon ayrildi");
    s->startAdvertising();  // tekrar görünür ol
  }
};

class LedOlaylari : public BLECharacteristicCallbacks {
  void onWrite(BLECharacteristic* c) override {
    String deger = c->getValue();
    digitalWrite(LED_PIN, deger == "1" ? HIGH : LOW);
    Serial.println("LED: " + deger);
  }
};

void setup() {
  Serial.begin(115200);
  pinMode(LED_PIN, OUTPUT);
  dht.begin();

  BLEDevice::init("KendinYap-Termometre");
  BLEServer* sunucu = BLEDevice::createServer();
  sunucu->setCallbacks(new SunucuOlaylari());
  BLEService* servis = sunucu->createService(SERVIS_UUID);

  sicaklikOzelligi = servis->createCharacteristic(SICAKLIK_UUID, BLECharacteristic::PROPERTY_READ | BLECharacteristic::PROPERTY_NOTIFY);
  sicaklikOzelligi->addDescriptor(new BLE2902());

  BLECharacteristic* ledOzelligi = servis->createCharacteristic(LED_UUID, BLECharacteristic::PROPERTY_WRITE);
  ledOzelligi->setCallbacks(new LedOlaylari());

  servis->start();
  BLEAdvertising* yayin = BLEDevice::getAdvertising();
  yayin->addServiceUUID(SERVIS_UUID);
  BLEDevice::startAdvertising();
  Serial.println("BLE hazir: KendinYap-Termometre");
}

void loop() {
  float sicaklik = dht.readTemperature();
  if (!isnan(sicaklik)) {
    sicaklikOzelligi->setValue(String(sicaklik, 1));
    if (telefonBagli) sicaklikOzelligi->notify();
  }
  delay(2000);
}
